// FindSet opens a result set matching current filters
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *EntrySummary) FindSet() bool {
	// A temporary record, and a record in a transaction, reads all at once: its in-memory
	// database or the transaction has one connection, which an open result set would block for
	// the statements of the loop (Modify while looping; on PostgreSQL a query while the rows are
	// read breaks the connection — "unexpected Parse response")
	if _, inTx := t.db.(*sql.Tx); t.temp != nil || inTx {
		return t.FindSetBuffered()
	}
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	t.bufferedRecords = nil
	tableName := fmt.Sprintf("%s$%s", t.company, EntrySummaryTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT entry_no, table_id, summary_type, total_quantity, total_reserved_quantity, total_available_quantity, current_reserved_quantity, available_page_id FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	query += t.forUpdate()

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for Entry_Summary: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record: in the result set after FindSet() or FindSetBuffered(),
// else from the current record in the current key (after Get, Find, FindFirst, FindLast)
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (FindSetBuffered, or after Get/Find)
//   - Next(-3): Skip backward 3 records (FindSetBuffered, or after Get/Find)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *EntrySummary) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var summary_typeNull sql.NullString
		var total_quantityNull sql.NullString
		var total_reserved_quantityNull sql.NullString
		var total_available_quantityNull sql.NullString
		var current_reserved_quantityNull sql.NullString

		err := t.currentRows.Scan(
			&t.Entry_no,
			&t.Table_id,
			&summary_typeNull,
			&total_quantityNull,
			&total_reserved_quantityNull,
			&total_available_quantityNull,
			&current_reserved_quantityNull,
			&t.Available_page_id,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Entry_Summary record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.Summary_type = types.NewText(summary_typeNull.String)
		t.Total_quantity, _ = types.NewDecimalFromString(total_quantityNull.String)
		t.Total_reserved_quantity, _ = types.NewDecimalFromString(total_reserved_quantityNull.String)
		t.Total_available_quantity, _ = types.NewDecimalFromString(total_available_quantityNull.String)
		t.Current_reserved_quantity, _ = types.NewDecimalFromString(current_reserved_quantityNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No record set (after Get, Find, FindFirst, FindLast): the next record in the current key
	// and direction within the filters, one step at a time (classic NEXT after FIND); a step
	// that finds none leaves the record on the last one reached
	if step == 0 {
		return false
	}
	for i := 0; i != step; {
		if step > 0 {
			if !t.findInKey(">", false) {
				return false
			}
			i++
		} else {
			if !t.findInKey("<", true) {
				return false
			}
			i--
		}
	}
	return true
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *EntrySummary) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := fmt.Sprintf("%s$%s", t.company, EntrySummaryTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT entry_no, table_id, summary_type, total_quantity, total_reserved_quantity, total_available_quantity, current_reserved_quantity, available_page_id FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for Entry_Summary: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &EntrySummary{}
		record.db = t.db
		record.temp = t.temp
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var summary_typeNull sql.NullString
		var total_quantityNull sql.NullString
		var total_reserved_quantityNull sql.NullString
		var total_available_quantityNull sql.NullString
		var current_reserved_quantityNull sql.NullString

		err := rows.Scan(
			&record.Entry_no,
			&record.Table_id,
			&summary_typeNull,
			&total_quantityNull,
			&total_reserved_quantityNull,
			&total_available_quantityNull,
			&current_reserved_quantityNull,
			&record.Available_page_id,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Entry_Summary record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.Summary_type = types.NewText(summary_typeNull.String)
		record.Total_quantity, _ = types.NewDecimalFromString(total_quantityNull.String)
		record.Total_reserved_quantity, _ = types.NewDecimalFromString(total_reserved_quantityNull.String)
		record.Total_available_quantity, _ = types.NewDecimalFromString(total_available_quantityNull.String)
		record.Current_reserved_quantity, _ = types.NewDecimalFromString(current_reserved_quantityNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate Entry_Summary records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

// copyFromBuffered copies field values from a buffered record to the current instance
func (t *EntrySummary) copyFromBuffered(record *EntrySummary) {
	t.Entry_no = record.Entry_no
	t.Table_id = record.Table_id
	t.Summary_type = record.Summary_type
	t.Total_quantity = record.Total_quantity
	t.Total_reserved_quantity = record.Total_reserved_quantity
	t.Total_available_quantity = record.Total_available_quantity
	t.Current_reserved_quantity = record.Current_reserved_quantity
	t.Available_page_id = record.Available_page_id
	t.StoreOldValues()
}

