// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *EntrySummary) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, EntrySummaryTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "entry_no":
			column = "entry_no"
		case "table_id":
			column = "table_id"
		case "total_quantity":
			column = "total_quantity"
		case "total_reserved_quantity":
			column = "total_reserved_quantity"
		case "total_available_quantity":
			column = "total_available_quantity"
		case "current_reserved_quantity":
			column = "current_reserved_quantity"
		case "available_page_id":
			column = "available_page_id"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Entry_Summary", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Entry_Summary.%s: %w", column, err)
		}
		switch column {
		case "entry_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Entry_Summary.%s: %w", column, err)
			}
			t.Entry_no = int(f)
		case "table_id":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Entry_Summary.%s: %w", column, err)
			}
			t.Table_id = int(f)
		case "total_quantity":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Entry_Summary.%s: %w", column, err)
			}
			t.Total_quantity = d
		case "total_reserved_quantity":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Entry_Summary.%s: %w", column, err)
			}
			t.Total_reserved_quantity = d
		case "total_available_quantity":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Entry_Summary.%s: %w", column, err)
			}
			t.Total_available_quantity = d
		case "current_reserved_quantity":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Entry_Summary.%s: %w", column, err)
			}
			t.Current_reserved_quantity = d
		case "available_page_id":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Entry_Summary.%s: %w", column, err)
			}
			t.Available_page_id = int(f)
		}
	}
	return nil
}

// LockTable locks the table until the transaction ends (classic LOCKTABLE): on Postgres a
