	t.Table_id = *new(int)
	t.Summary_type = *new(types.Text)
	t.Total_quantity = *new(types.Decimal)
	t.Total_reserved_quantity = *new(types.Decimal)
	t.Total_available_quantity = *new(types.Decimal)
	t.Current_reserved_quantity = *new(types.Decimal)
	t.Available_page_id = *new(int)
